{"code": "import os
from PIL import Image

# Check if there are any valid image files
def count_valid_images(directory):
    valid_count = 0
    lfs_count = 0
    total = 0
    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.lower().endswith(('.jpg', '.jpeg', '.png')):
                total += 1
                path = os.path.join(root, file)
                try:
                    with open(path, 'rb') as f:
                        header = f.read(50)
                    if header.startswith(b'version https://git-lfs.github.com'):
                        lfs_count += 1
                    else:
                        try:
                            img = Image.open(path)
                            img.verify()
                            valid_count += 1
                        except:
                            lfs_count += 1
                except:
                    pass
    return total, valid_count, lfs_count

train_dir = 'data_small/flower_data/train'
total, valid, lfs = count_valid_images(train_dir)
print(f"Total images found: {total}")
print(f"Valid images: {valid}")
print(f"LFS/Invalid images: {lfs}")"}

